/** Generated by npm run embed:og-fonts — do not edit. */
function decode(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export const OG_FONT_BUFFERS: Uint8Array[] = [
  decode(''),
  decode(''),
];
